package com.apptomo.v4.aireactechartdashboard.workerdashboard.repository;
import com.apptomo.v4.aireactechartdashboard.workerdashboard.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.sql.Timestamp; import java.time.*; import java.util.*;
// 20260928 추가
@Repository @RequiredArgsConstructor public class WorkerDashboardRepository {private final NamedParameterJdbcTemplate jdbc; private static Double d(Object v){return v==null?null:((Number)v).doubleValue();} private static String s(Object v){return v==null?null:String.valueOf(v).replace(' ','T');}
 public List<WorkerNodeDto> nodes(){String sql="WITH h AS (SELECT DISTINCT hostname FROM public.ax_metrics_node WHERE hostname IS NOT NULL UNION SELECT DISTINCT hostname FROM public.ax_metrics_sqream_cluster_nodes WHERE hostname IS NOT NULL), n AS (SELECT DISTINCT ON(hostname) hostname,hostip,cpu_usage_percent,memory_usage_percent,disk_usage_percent FROM public.ax_metrics_node WHERE hostname IS NOT NULL ORDER BY hostname,collect_time DESC), g AS (SELECT ni.hostname,MAX(dm.gr_engine_active_percent*100.0) gpu FROM public.ax_metrics_gpu_dcgmi_metric dm JOIN public.ax_metrics_gpu_nvidia_smi_info ni ON ni.id=dm.nvidia_smi_id GROUP BY ni.hostname) SELECT h.hostname,n.hostip,n.cpu_usage_percent,n.memory_usage_percent,n.disk_usage_percent,g.gpu FROM h LEFT JOIN n USING(hostname) LEFT JOIN g USING(hostname) ORDER BY regexp_replace(h.hostname,'\\D','','g')::bigint NULLS LAST,h.hostname"; List<WorkerNodeDto> out=new ArrayList<>();for(Map<String,Object> r:jdbc.queryForList(sql,new MapSqlParameterSource())){WorkerNodeDto x=new WorkerNodeDto();x.hostname=s(r.get("hostname"));x.hostip=s(r.get("hostip"));x.latestCpu=d(r.get("cpu_usage_percent"));x.latestMemory=d(r.get("memory_usage_percent"));x.latestDisk=d(r.get("disk_usage_percent"));x.latestGpu=d(r.get("gpu"));out.add(x);}return out;}
 public List<WorkerMetricDto> metrics(String h,LocalDateTime st,LocalDateTime en){MapSqlParameterSource p=new MapSqlParameterSource().addValue("h",h).addValue("st",Timestamp.valueOf(st)).addValue("en",Timestamp.valueOf(en));String sql="WITH times AS (SELECT collect_time FROM public.ax_metrics_node WHERE hostname=:h AND collect_time BETWEEN :st AND :en UNION SELECT dm.snapshot_time FROM public.ax_metrics_gpu_dcgmi_metric dm JOIN public.ax_metrics_gpu_nvidia_smi_info ni ON ni.id=dm.nvidia_smi_id WHERE ni.hostname=:h AND dm.snapshot_time BETWEEN :st AND :en), t AS (SELECT DISTINCT date_trunc('second',collect_time) collect_time FROM times), n AS (SELECT date_trunc('second',collect_time) collect_time,AVG(cpu_usage_percent) cpu,AVG(memory_usage_percent) memory,AVG(disk_usage_percent) disk FROM public.ax_metrics_node WHERE hostname=:h AND collect_time BETWEEN :st AND :en GROUP BY 1), g AS (SELECT date_trunc('second',dm.snapshot_time) collect_time,AVG(dm.gr_engine_active_percent*100.0) gpu FROM public.ax_metrics_gpu_dcgmi_metric dm JOIN public.ax_metrics_gpu_nvidia_smi_info ni ON ni.id=dm.nvidia_smi_id WHERE ni.hostname=:h AND dm.snapshot_time BETWEEN :st AND :en GROUP BY 1) SELECT t.collect_time,g.gpu,n.cpu,n.memory,n.disk FROM t LEFT JOIN n USING(collect_time) LEFT JOIN g USING(collect_time) ORDER BY t.collect_time";List<WorkerMetricDto> out=new ArrayList<>();for(Map<String,Object> r:jdbc.queryForList(sql,p)){WorkerMetricDto x=new WorkerMetricDto();x.collectTime=s(r.get("collect_time"));x.gpu=d(r.get("gpu"));x.cpu=d(r.get("cpu"));x.memory=d(r.get("memory"));x.disk=d(r.get("disk"));out.add(x);}return out;}
}
